begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
insert into auth.users(id,email) values ('10000000-0000-4000-8000-000000000001','report-a@example.test'),('10000000-0000-4000-8000-000000000002','report-b@example.test');
insert into auth.sessions(id,user_id) values ('20000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001'),('20000000-0000-4000-8000-000000000002','10000000-0000-4000-8000-000000000002');
insert into finance.profiles(id,display_name) values ('10000000-0000-4000-8000-000000000001','Synthetic A'),('10000000-0000-4000-8000-000000000002','Synthetic B');
insert into finance.households(id,name) values ('30000000-0000-4000-8000-000000000001','Synthetic A'),('30000000-0000-4000-8000-000000000002','Synthetic B');
insert into finance.household_members(id,household_id,user_id,display_name) values ('40000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001','Synthetic A'),('40000000-0000-4000-8000-000000000002','30000000-0000-4000-8000-000000000002','10000000-0000-4000-8000-000000000002','Synthetic B');
select ok(not has_function_privilege('anon','api.reporting_snapshot()','EXECUTE'),'anonymous reporting denied');
select ok(not prosecdef and provolatile='s','stable invoker report') from pg_proc where oid='api.reporting_snapshot()'::regprocedure;
select is((select proconfig[1] from pg_proc where oid='api.reporting_snapshot()'::regprocedure),'search_path=""','fixed empty search path');
set local role anon;
select throws_ok('select api.reporting_snapshot()','42501',null,'anonymous call denied');
set local role authenticated;
select is(api.reporting_snapshot()->'error'->>'code','NOT_AUTHORIZED','missing session denied');
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000001","role":"authenticated","session_id":"20000000-0000-4000-8000-000000000001"}',true);
select is(api.reporting_snapshot()->>'ok','true','live session report');
select is(jsonb_array_length(api.reporting_snapshot()->'snapshot'->'households'),1,'only authorized household');
select is(api.reporting_snapshot()->'snapshot'->'households'->0->>'id','30000000-0000-4000-8000-000000000001','household A scope');
select is(api.reporting_snapshot()->'snapshot'->>'size','2','explicit complete snapshot size');
select is(api.reporting_snapshot()->'snapshot'->'references','[]'::jsonb,'no import matching references loaded');
select throws_ok($$select api.reporting_snapshot('30000000-0000-4000-8000-000000000002'::uuid)$$,'42883',null,'no caller-forged household argument');
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000002","role":"authenticated","session_id":"20000000-0000-4000-8000-000000000002"}',true);
select is(api.reporting_snapshot()->'snapshot'->'households'->0->>'id','30000000-0000-4000-8000-000000000002','household B scope');
reset role;
update finance.household_members set status='REVOKED' where id='40000000-0000-4000-8000-000000000002';
set local role authenticated;
select is(api.reporting_snapshot()->'snapshot'->'households','[]'::jsonb,'unchanged revoked JWT sees empty report');
select is(api.reporting_snapshot()->'snapshot'->'members','[]'::jsonb,'revoked attribution hidden');
reset role;
delete from auth.sessions where id='20000000-0000-4000-8000-000000000002';
set local role authenticated;
select is(api.reporting_snapshot()->'error'->>'code','NOT_AUTHORIZED','deleted session denies reporting');
reset role;
delete from auth.users where id='10000000-0000-4000-8000-000000000002';
set local role authenticated;
select is(api.reporting_snapshot()->'error'->>'code','NOT_AUTHORIZED','deleted Auth user denies reporting');
reset role;
-- Overflow is explicit; never return a partial success when an authorized collection exceeds its bound.
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000001","role":"authenticated","session_id":"20000000-0000-4000-8000-000000000001"}',true);
select is(api.create_account('{"account":{"id":"50000000-0000-4000-8000-000000000001","householdId":"30000000-0000-4000-8000-000000000001","name":"Synthetic large observations","ownership":{"kind":"HOUSEHOLD"},"type":"INVESTMENT","currency":"ILS","valuationCurrency":"ILS","balancePolicy":"OBSERVED","status":"ACTIVE"},"version":1,"manualSourceId":"60000000-0000-4000-8000-000000000001"}'::jsonb)->>'ok','true','bounded-response fixture account');
insert into finance.balance_observations(id,household_id,account_id,source_id,observation_date,amount,currency,coverage,note)
select gen_random_uuid(),'30000000-0000-4000-8000-000000000001','50000000-0000-4000-8000-000000000001','60000000-0000-4000-8000-000000000001',date '1000-01-01'+v,1,'ILS','COMPLETE',repeat('s',500) from generate_series(1,25000) v;
set local role authenticated;
select is(api.reporting_snapshot()->>'ok','false','16 MiB serialized-response overflow fails explicitly below row bounds');
select ok(not api.reporting_snapshot()?'snapshot','byte overflow never returns partial data');
reset role;
create temp table synthetic_homes as select gen_random_uuid() id from generate_series(1,100);
insert into finance.households(id,name) select id,'Synthetic overflow' from synthetic_homes;
insert into finance.household_members(household_id,user_id,display_name) select id,'10000000-0000-4000-8000-000000000001','Synthetic A' from synthetic_homes;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000001","role":"authenticated","session_id":"20000000-0000-4000-8000-000000000001"}',true);
select is(api.reporting_snapshot()->>'ok','false','oversize fails explicitly');
select is(api.reporting_snapshot()->'error'->>'code','INVALID_INPUT','overflow returns fixed SafeError');
select ok(not api.reporting_snapshot()?'snapshot','overflow does not serialize a truncated snapshot');
select * from finish();
rollback;
